document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("bricks-form"),t=document.getElementById("bricks-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("bricks-area").value),a=parseFloat(document.getElementById("bricks-length").value),l=parseFloat(document.getElementById("bricks-height").value),s=parseFloat(document.getElementById("bricks-width").value),r=parseFloat(document.getElementById("bricks-joint").value)||0,i=parseFloat(document.getElementById("bricks-layer").value);if(n<=0||a<=0||l<=0||s<=0||i<=0)return t.textContent="Please enter all brick dimensions, wall area, and select wall type.",void 0;const c=1/((a+r)/12*((l+r)/12)),d=n*c*i,o=1.1*d,p=n*(r/12)*i*.3,u=Math.ceil(p/.6);t.innerHTML=`\n        <div class="result-section">\n          <h4>Bricks Needed:</h4>\n          <p><strong>${Math.ceil(d)} bricks</strong> (exact calculation)</p>\n          <p><strong>${Math.ceil(o)} bricks</strong> (with 10% waste allowance)</p>\n          <p>Rate: ${c.toFixed(1)} bricks per sq ft</p>\n        </div>\n        <div class="result-materials">\n          <h4>Additional Materials:</h4>\n          <p>Mortar bags (80lb): ~${u} bags</p>\n          <p>Wall area: ${n} sq ft</p>\n          <p>Wall thickness: ${1===i?"Single wythe":2===i?"Double wythe":"Cavity wall"}</p>\n        </div>\n        <div class="result-tips">\n          <p><em>💡 Always order 5-10% extra bricks for breakage and future repairs</em></p>\n          <p><em>🧱 Standard delivery is by the pallet (typically 500-1000 bricks)</em></p>\n        </div>\n      `})});